using System;using System.Linq;using System.Reflection;using NUnit.Framework;
namespace LWS.TruckSubmarine.Tests {
 public sealed class SubmarineRulesTests {
  Type type,kind;object rules;const BindingFlags Any=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
  object Call(string name,params object[]args)=>type.GetMethod(name,Any).Invoke(rules,args);T Get<T>(string name)=>type.GetField(name,Any)!=null?(T)type.GetField(name,Any).GetValue(rules):(T)type.GetProperty(name,Any).GetValue(rules);object Kind(string name)=>Enum.Parse(kind,name);int[] Points=>Get<int[]>("points");
  void Tick(float s){for(int i=0;i<(int)Math.Ceiling(s/.05f);i++)Call("Tick",.05f);}void Dive(){Tick(3.1f);Assert.That(Get<object>("Phase").ToString(),Is.EqualTo("Diving"));}
  [SetUp]public void Reset(){type=Type.GetType("LWS.TruckSubmarine.SubmarineRules, Assembly-CSharp",true);kind=Type.GetType("LWS.TruckSubmarine.SubmarineCargoKind, Assembly-CSharp",true);rules=Activator.CreateInstance(type);Call("Reset",4,0);}
  [Test]public void CountdownAndPickupCannotInventDeliveredPoints(){Assert.That((bool)Call("Grab",0,0),Is.False);Dive();Assert.That((bool)Call("Grab",0,0),Is.True);Assert.That(Points,Is.All.Zero);Assert.That(Get<int[]>("deliveries"),Is.All.Zero);}
  [Test]public void OnePhysicalOwnerAndOneCargoPerTruck(){Dive();Assert.That((bool)Call("Grab",0,3),Is.True);Assert.That((bool)Call("Grab",1,3),Is.False);Assert.That((bool)Call("Grab",0,4),Is.False);Assert.That(Get<int[]>("carried")[0],Is.EqualTo(3));}
  [Test]public void ReleaseRetainsAvailablePhysicalTreasureWithoutScoring(){Dive();Call("Grab",0,4);Assert.That((bool)Call("Release",1,4),Is.False);Assert.That((bool)Call("Release",0,4),Is.True);Assert.That((bool)Call("Available",4),Is.True);Assert.That(Points,Is.All.Zero);Assert.That((bool)Call("Grab",2,4),Is.True);}
  [Test]public void OnlyRecordedCarrierCanBankAndOneLifeBanksOnce(){Dive();Call("Grab",2,7);Assert.That((int)Call("Bank",1,7,Kind("Gold"),95f),Is.Zero);Assert.That((int)Call("Bank",2,7,Kind("Gold"),95f),Is.EqualTo(150));Assert.That((int)Call("Bank",2,7,Kind("Gold"),95f),Is.Zero);Assert.That((bool)Call("Grab",3,7),Is.False);Assert.That(Points[2],Is.EqualTo(150));Assert.That(Get<int[]>("deliveries")[2],Is.EqualTo(1));Assert.That(Get<int[]>("carried")[2],Is.EqualTo(-1));}
  [TestCase("Chest",20,30)][TestCase("Gold",46,100)][TestCase("Artifact",100,120)][TestCase("Cargo",140,100)][TestCase("Salvage",170,80)]public void ActualOriginalDepthAndCargoKindSetValue(string name,float depth,int expected){Assert.That((int)type.GetMethod("Value").Invoke(null,new object[]{Kind(name),depth}),Is.EqualTo(expected));}
  [Test]public void InvalidOrUnheldDeliveryCannotConsumeCargo(){Dive();Assert.That((int)Call("Bank",0,0,Kind("Gold"),30f),Is.Zero);Call("Grab",0,0);Assert.That((int)Call("Bank",0,0,Kind("Gold"),float.NaN),Is.Zero);Assert.That((int)Call("Bank",0,0,Kind("Gold"),30f),Is.EqualTo(50));}
  [Test]public void SafeDepthDoesNotDamageHullAndDeepPressureIsBounded(){Dive();for(int i=0;i<100;i++)Call("Pressure",0,60f,.05f);Assert.That(Get<float[]>("integrity")[0],Is.EqualTo(100));Call("Pressure",0,150f,1000f);Assert.That(Get<float[]>("integrity")[0],Is.GreaterThanOrEqualTo(99.1f));Assert.That(Get<float[]>("deepest")[0],Is.EqualTo(150));}
  [Test]public void PressureFailureRetiresOnlyItsOwnerAndNeverAwardsScore(){Dive();for(int i=0;i<400;i++)Call("Pressure",1,160f,.05f);Assert.That(Get<bool[]>("retired")[1],Is.True);Assert.That(Get<bool[]>("retired")[0],Is.False);Assert.That((bool)Call("Grab",1,2),Is.False);Assert.That(Points,Is.All.Zero);}
  [Test]public void TimeoutTiesAndRematchRestoreFiniteLifeState(){Dive();Call("Grab",0,0);Call("Bank",0,0,Kind("Chest"),10f);Call("Grab",1,1);Call("Bank",1,1,Kind("Chest"),10f);Tick(181);Assert.That(Get<bool>("Complete"),Is.True);Assert.That((int)Call("Place",0),Is.EqualTo(1));Assert.That((int)Call("Place",1),Is.EqualTo(1));Call("Reset",4,2);Assert.That(Get<bool>("Complete"),Is.False);Assert.That(Points,Is.All.Zero);Assert.That(Get<float[]>("integrity"),Is.All.EqualTo(100));Assert.That(Get<float>("RatedDepth"),Is.EqualTo(150));Assert.That((bool)Call("Available",0),Is.True);}
  [Test]public void InvalidClockCannotAdvanceOrDamage(){Call("Tick",float.NaN);Call("Tick",float.PositiveInfinity);Call("Tick",-1f);Assert.That(Get<float>("Clock"),Is.Zero);Dive();Call("Pressure",0,float.NaN,.1f);Call("Pressure",0,150f,float.NaN);Assert.That(Get<float[]>("integrity")[0],Is.EqualTo(100));}
 }
}
